insert into public.decks (
  id, owner_id, name, format, notes, visibility, allow_forks, is_precon,
  commander_scryfall_id, commander_name, commander_type_line, commander_mana_cost,
  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  '7fcea7eb-a0d8-5f78-901f-4bb4c90650ae'::uuid, null, 'Angels: They''re Just Like Us but Cooler and with Wings', 'commander', 'Angels: They''re Just Like Us but Cooler and with Wings is an official Commander precon from SLD, released 2023-08-14.', 'public', true, true,
  'd1cfc318-9c3e-471f-90eb-dc76454da957', 'Gisela, the Broken Blade // Brisela, Voice of Nightmares', 'Legendary Creature — Angel Horror', '{2}{W}{W}',
  'https://cards.scryfall.io/normal/front/d/1/d1cfc318-9c3e-471f-90eb-dc76454da957.jpg', 'https://cards.scryfall.io/art_crop/front/d/1/d1cfc318-9c3e-471f-90eb-dc76454da957.jpg', ARRAY['W']::text[], ARRAY['W']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
  allow_forks = excluded.allow_forks,
  is_precon = excluded.is_precon,
  commander_scryfall_id = excluded.commander_scryfall_id,
  commander_name = excluded.commander_name,
  commander_type_line = excluded.commander_type_line,
