) values (
  '011c5bdf-a8c6-5fcf-930a-84eb6c946420'::uuid, null, 'Fae Dominion', 'commander', 'Fae Dominion is an official Commander precon from WOC, released 2023-09-08.', 'public', true, true,
  '03fab911-7bd4-45fa-ba07-cd0e51b0cd95', 'Tegwyll, Duke of Splendor', 'Legendary Creature — Faerie Noble', '{1}{U}{B}',
  'https://cards.scryfall.io/normal/front/0/3/03fab911-7bd4-45fa-ba07-cd0e51b0cd95.jpg', 'https://cards.scryfall.io/art_crop/front/0/3/03fab911-7bd4-45fa-ba07-cd0e51b0cd95.jpg', ARRAY['U', 'B']::text[], ARRAY['U', 'B']::text[]
) on conflict (id) do update set
