  color_identity, oracle_text, quantity, board
)
select v.deck_id, v.scryfall_id, v.card_name, v.image_uri, v.mana_cost, v.type_line, v.colors,
  v.color_identity, v.oracle_text, v.quantity, v.board
from (values
  ('73bf8980-4f36-57a1-aa2e-5af96bb25db8'::uuid, '19e96521-b4ce-4a36-a887-200e05ccc804', 'Abraded Bluffs', 'https://cards.scryfall.io/normal/front/1/9/19e96521-b4ce-4a36-a887-200e05ccc804.jpg', null::text, 'Land — Desert', '{}'::text[], ARRAY['W', 'R']::text[], 'This land enters tapped.
